#include "../src/MeterState.h"
#include "../src/InputRoutePreferences.h"
#include <cassert>
#include <iostream>
int main(int argc,char** argv){assert(argc==2);auto directory=juce::File(juce::String::fromUTF8(argv[1]));directory.createDirectory();auto file=directory.getChildFile("weighted-runtime-"+juce::Uuid().toString()+".json");MeterState meters(file);auto card=*meters.primaryCard();card.deviceKey="CoreAudio / OCTA";card.channel=1;card.metric=5;card.weight=2;card.leqSeconds=1;assert(meters.update(card));InputLevels::Peak block;block.valid=block.weightedValid=true;block.samples=480;block.weightedSquares[1]=.01*480;for(int n=1;n<=100;++n){meters.feedWeighted(card.id,card.deviceKey,1,block,(std::uint64_t)n,48000.,94.);if(n<100)assert(!meters.runtime(card.id).current);}assert(meters.runtime(card.id).current&&std::abs(*meters.runtime(card.id).current-74.)<1.e-6);assert(meters.runtime(card.id).leqFill&&*meters.runtime(card.id).leqFill==1.);assert(meters.resetLeq(card.id));assert(!meters.runtime(card.id).current&&!meters.runtime(card.id).leqFill);meters.feedWeighted(card.id,card.deviceKey,1,block,101,48000.,{});assert(!meters.runtime(card.id).current);auto routeFile=directory.getChildFile("route-"+juce::Uuid().toString()+".json");InputRoutePreferences route;route.routes[0]={"CoreAudio / OCTA",1,5};route.outputDevice="CoreAudio / OCTA";route.outputChannel=1;assert(route.save(routeFile));auto restored=InputRoutePreferences::read(routeFile);assert(restored&&restored->outputStored&&restored->outputDevice==route.outputDevice&&restored->outputChannel==1&&restored->routes[0].ref==5);std::cout<<"PASS Leq 1 s, reset, calibration gate, loop route persistence\n";}
